INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('2ac888d2-9fdb-5c31-8166-f443d2ef7219','TEXT','A passage 1','The mangrove restoration project at the eucalypt reserve began with a simple observation. Eli noticed that the first plan treated several small problems as though they were the same problem. The team changed its method: they recorded each issue, tested one change at a time and compared the new result with the original notes.
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('1d069dd9-ad75-57f2-821f-d6685282a1db', 'MULTIPLE_CHOICE', 9, 'READING', 'Main idea and purpose', 4, NULL, NULL, 'Which statement best expresses the main idea?', '[{"label":"A","text":"A competition is cancelled without explanation."},{"label":"B","text":"The text explains how people respond to a practical problem and use evidence to guide the next step."},{"label":"C","text":"A new product is advertised to the public."},{"label":"D","text":"A character solves a problem instantly."}]'::jsonb, '{"value":"B"}'::jsonb, 'The answer summarises the central problem and response.', 'PUBLISHED', NULL, 'PREMIUM', 'EASY', 1, 'COMPREHENSION', 'Reading for meaning', NULL, '2ac888d2-9fdb-5c31-8166-f443d2ef7219', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','1d069dd9-ad75-57f2-821f-d6685282a1db',1,'b41074e3-8b66-56bf-bf0a-447605cfb47f','c442fd55-8bdd-57c4-b21e-046874306eb1') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('ff42f9f0-4711-5e83-bf9a-ecab285e9204', 'MULTIPLE_CHOICE', 9, 'READING', 'Locating information', 5, NULL, NULL, 'Which detail best supports the main idea?', '[{"label":"A","text":"The project is held outdoors."},{"label":"B","text":"The group uses a timetable."},{"label":"C","text":"The group changes its approach after comparing information with what is happening."},{"label":"D","text":"The volunteers arrive in the afternoon."}]'::jsonb, '{"value":"C"}'::jsonb, 'This detail directly describes the change that drives the text.', 'PUBLISHED', NULL, 'PREMIUM', 'EASY', 1, 'COMPREHENSION', 'Reading for meaning', NULL, '2ac888d2-9fdb-5c31-8166-f443d2ef7219', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','ff42f9f0-4711-5e83-bf9a-ecab285e9204',2,'b41074e3-8b66-56bf-bf0a-447605cfb47f','c442fd55-8bdd-57c4-b21e-046874306eb1') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('bab1841d-d1c2-52cf-b077-38d8c38b01a9', 'MULTIPLE_CHOICE', 9, 'READING', 'Inference', 4, NULL, NULL, 'What can the reader infer about the group''s approach?', '[{"label":"A","text":"They never compare results."},{"label":"B","text":"The people involved value testing an idea before committing to it."},{"label":"C","text":"They believe the first idea is always best."},{"label":"D","text":"They avoid all decisions."}]'::jsonb, '{"value":"B"}'::jsonb, 'Their actions show a preference for evidence and testing.', 'PUBLISHED', NULL, 'PREMIUM', 'EASY', 1, 'ANALYSIS', 'Reading for meaning', NULL, '2ac888d2-9fdb-5c31-8166-f443d2ef7219', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','bab1841d-d1c2-52cf-b077-38d8c38b01a9',3,'b41074e3-8b66-56bf-bf0a-447605cfb47f','c442fd55-8bdd-57c4-b21e-046874306eb1') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('0e1fc519-4a58-5595-8e22-4c73bc4be4da', 'MULTIPLE_CHOICE', 9, 'READING', 'Vocabulary in context', 5, NULL, NULL, 'In the passage, “trial” is closest in meaning to which phrase?', '[{"label":"A","text":"a test of an idea"},{"label":"B","text":"an unrelated opinion"},{"label":"C","text":"a rule with no exceptions"},{"label":"D","text":"a final result that cannot change"}]'::jsonb, '{"value":"A"}'::jsonb, 'The surrounding context supports the meaning “a test of an idea.”', 'PUBLISHED', NULL, 'PREMIUM', 'EASY', 1, 'COMPREHENSION', 'Reading for meaning', NULL, '2ac888d2-9fdb-5c31-8166-f443d2ef7219', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','0e1fc519-4a58-5595-8e22-4c73bc4be4da',4,'b41074e3-8b66-56bf-bf0a-447605cfb47f','c442fd55-8bdd-57c4-b21e-046874306eb1') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('4147f7c0-8ce0-5117-bab9-964bc1578bed', 'MULTIPLE_CHOICE', 9, 'READING', 'Text structure', 4, NULL, NULL, 'How is the text mainly organised?', '[{"label":"A","text":"It gives instructions with no explanation."},{"label":"B","text":"It lists unrelated facts only."},{"label":"C","text":"It presents a problem but gives no response."},{"label":"D","text":"It introduces a situation, describes a response and explains what was learned."}]'::jsonb, '{"value":"D"}'::jsonb, 'The text moves from situation to response to implication.', 'PUBLISHED', NULL, 'PREMIUM', 'EASY', 1, 'ANALYSIS', 'Reading for meaning', NULL, '2ac888d2-9fdb-5c31-8166-f443d2ef7219', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','4147f7c0-8ce0-5117-bab9-964bc1578bed',5,'b41074e3-8b66-56bf-bf0a-447605cfb47f','c442fd55-8bdd-57c4-b21e-046874306eb1') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('dcaa1be3-ff77-5d9c-a515-eed0a07f4a51', 'MULTIPLE_CHOICE', 9, 'READING', 'Evidence and support', 5, NULL, NULL, 'Which statement is the strongest evidence for the claim that the team used evidence?', '[{"label":"A","text":"The passage explains that the team compared new results with earlier notes."},{"label":"B","text":"The passage mentions an afternoon."},{"label":"C","text":"The setting is a community site."},{"label":"D","text":"A person''s name is included."}]'::jsonb, '{"value":"A"}'::jsonb, 'The selected detail directly describes comparison of results.', 'PUBLISHED', NULL, 'PREMIUM', 'EASY', 1, 'ANALYSIS', 'Reading for meaning', NULL, '2ac888d2-9fdb-5c31-8166-f443d2ef7219', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','dcaa1be3-ff77-5d9c-a515-eed0a07f4a51',6,'b41074e3-8b66-56bf-bf0a-447605cfb47f','c442fd55-8bdd-57c4-b21e-046874306eb1') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('f4d01d2b-7ac4-59fa-a129-c0fc01540ea8', 'MULTIPLE_CHOICE', 9, 'READING', 'Author purpose', 4, NULL, NULL, 'What is the author''s main purpose?', '[{"label":"A","text":"To explain an approach to solving a practical problem and why it is useful."},{"label":"B","text":"To provide cooking directions."},{"label":"C","text":"To tell a joke."},{"label":"D","text":"To advertise a service."}]'::jsonb, '{"value":"A"}'::jsonb, 'The text explains an approach and its implications.', 'PUBLISHED', NULL, 'PREMIUM', 'EASY', 1, 'ANALYSIS', 'Reading for meaning', NULL, '2ac888d2-9fdb-5c31-8166-f443d2ef7219', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','f4d01d2b-7ac4-59fa-a129-c0fc01540ea8',7,'b41074e3-8b66-56bf-bf0a-447605cfb47f','c442fd55-8bdd-57c4-b21e-046874306eb1') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('208b128a-7170-5e9a-8226-6a9dae260108', 'MULTIPLE_CHOICE', 9, 'READING', 'Evaluation', 5, NULL, NULL, 'Which evaluation of the author''s viewpoint is best supported?', '[{"label":"A","text":"The author rejects all trialling."},{"label":"B","text":"The author supports careful testing rather than relying on an untested first idea."},{"label":"C","text":"The author prefers decisions made without evidence."},{"label":"D","text":"The author says results never matter."}]'::jsonb, '{"value":"B"}'::jsonb, 'The text consistently values testing and evidence.', 'PUBLISHED', NULL, 'PREMIUM', 'EASY', 1, 'ANALYSIS', 'Reading for meaning', NULL, '2ac888d2-9fdb-5c31-8166-f443d2ef7219', TRUE, NULL) ;
