INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('ca691939-1395-57f4-9d15-2176cf8fc3b0', 'MULTIPLE_CHOICE', 9, 'READING', 'Author purpose', 4, NULL, NULL, 'What is the author''s main purpose?', '[{"label":"A","text":"To explain an approach to solving a practical problem and why it is useful."},{"label":"B","text":"To provide cooking directions."},{"label":"C","text":"To tell a joke."},{"label":"D","text":"To advertise a service."}]'::jsonb, '{"value":"A"}'::jsonb, 'The text explains an approach and its implications.', 'PUBLISHED', NULL, 'PREMIUM', 'EASY', 1, 'ANALYSIS', 'Reading for meaning', NULL, '173e021e-7f2a-56b9-90bd-fa014241128a', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','ca691939-1395-57f4-9d15-2176cf8fc3b0',15,'b41074e3-8b66-56bf-bf0a-447605cfb47f','c442fd55-8bdd-57c4-b21e-046874306eb1') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('283e9333-cbe8-56d0-8c10-db544deaf635', 'MULTIPLE_CHOICE', 9, 'READING', 'Evaluation', 5, NULL, NULL, 'Which evaluation of the author''s viewpoint is best supported?', '[{"label":"A","text":"The author rejects all trialling."},{"label":"B","text":"The author supports careful testing rather than relying on an untested first idea."},{"label":"C","text":"The author prefers decisions made without evidence."},{"label":"D","text":"The author says results never matter."}]'::jsonb, '{"value":"B"}'::jsonb, 'The text consistently values testing and evidence.', 'PUBLISHED', NULL, 'PREMIUM', 'EASY', 1, 'ANALYSIS', 'Reading for meaning', NULL, '173e021e-7f2a-56b9-90bd-fa014241128a', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','283e9333-cbe8-56d0-8c10-db544deaf635',16,'b41074e3-8b66-56bf-bf0a-447605cfb47f','c442fd55-8bdd-57c4-b21e-046874306eb1') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('4708da1d-b163-56f0-9e13-3eb87d7ffc20','TEXT','B passage 1','At the community garden, the stormwater gardens project divided volunteers into small teams. One team wanted to begin immediately, while another argued for a short planning session. Arun listened to both sides and suggested a trial that would reveal which approach worked best. By the end of the afternoon, the group had discovered that the best solution was not the fastest idea or the most complicated one. It was the idea that made the next decision easier.',NULL,NULL,NULL,9,'READING','PUBLISHED',NULL);
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('45dcf9de-e2ac-58fe-9dd0-fdeaf038ae3f', 'MULTIPLE_CHOICE', 9, 'READING', 'Main idea and purpose', 4, NULL, NULL, 'Which statement best expresses the main idea?', '[{"label":"A","text":"A competition is cancelled without explanation."},{"label":"B","text":"The text explains how people respond to a practical problem and use evidence to guide the next step."},{"label":"C","text":"A new product is advertised to the public."},{"label":"D","text":"A character solves a problem instantly."}]'::jsonb, '{"value":"B"}'::jsonb, 'The answer summarises the central problem and response.', 'PUBLISHED', NULL, 'PREMIUM', 'EASY', 1, 'COMPREHENSION', 'Reading for meaning', NULL, '4708da1d-b163-56f0-9e13-3eb87d7ffc20', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','45dcf9de-e2ac-58fe-9dd0-fdeaf038ae3f',17,'b41074e3-8b66-56bf-bf0a-447605cfb47f','01bfcbba-c4c0-5d9f-b429-2ad1d702886b') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('2368416e-7622-532b-8892-c3f72c1ff9f8', 'MULTIPLE_CHOICE', 9, 'READING', 'Locating information', 5, NULL, NULL, 'Which detail best supports the main idea?', '[{"label":"A","text":"The project is held outdoors."},{"label":"B","text":"The group uses a timetable."},{"label":"C","text":"The group changes its approach after comparing information with what is happening."},{"label":"D","text":"The volunteers arrive in the afternoon."}]'::jsonb, '{"value":"C"}'::jsonb, 'This detail directly describes the change that drives the text.', 'PUBLISHED', NULL, 'PREMIUM', 'EASY', 1, 'COMPREHENSION', 'Reading for meaning', NULL, '4708da1d-b163-56f0-9e13-3eb87d7ffc20', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','2368416e-7622-532b-8892-c3f72c1ff9f8',18,'b41074e3-8b66-56bf-bf0a-447605cfb47f','01bfcbba-c4c0-5d9f-b429-2ad1d702886b') ON CONFLICT (exam_id,question_id) DO NOTHING;
