INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('90945453-5ee8-5cb4-9859-63e56c757449', 'MULTIPLE_CHOICE', 9, 'READING', 'Author purpose', 4, NULL, NULL, 'What is the author''s main purpose?', '[{"label":"A","text":"To explain an approach to solving a practical problem and why it is useful."},{"label":"B","text":"To provide cooking directions."},{"label":"C","text":"To tell a joke."},{"label":"D","text":"To advertise a service."}]'::jsonb, '{"value":"A"}'::jsonb, 'The text explains an approach and its implications.', 'PUBLISHED', NULL, 'PREMIUM', 'EASY', 1, 'ANALYSIS', 'Reading for meaning', NULL, 'ec9fc8b7-0941-5aea-aa8f-895b572f18cb', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','90945453-5ee8-5cb4-9859-63e56c757449',31,'b41074e3-8b66-56bf-bf0a-447605cfb47f','01bfcbba-c4c0-5d9f-b429-2ad1d702886b') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('ce94853b-42d5-5a49-96f4-c3f01bf3c98c', 'MULTIPLE_CHOICE', 9, 'READING', 'Evaluation', 5, NULL, NULL, 'Which evaluation of the author''s viewpoint is best supported?', '[{"label":"A","text":"The author rejects all trialling."},{"label":"B","text":"The author supports careful testing rather than relying on an untested first idea."},{"label":"C","text":"The author prefers decisions made without evidence."},{"label":"D","text":"The author says results never matter."}]'::jsonb, '{"value":"B"}'::jsonb, 'The text consistently values testing and evidence.', 'PUBLISHED', NULL, 'PREMIUM', 'EASY', 1, 'ANALYSIS', 'Reading for meaning', NULL, 'ec9fc8b7-0941-5aea-aa8f-895b572f18cb', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','ce94853b-42d5-5a49-96f4-c3f01bf3c98c',32,'b41074e3-8b66-56bf-bf0a-447605cfb47f','01bfcbba-c4c0-5d9f-b429-2ad1d702886b') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('3a9e8c47-e761-5d33-b882-374177109c8d','TEXT','B_LATE passage 1','Some people in the school athletics carnival support expanding the river bird counts project, while others want to see more evidence first. Supporters point to improved participation and clearer results from the trial. Critics agree the early signs are useful but argue that a larger rollout should happen in stages. A practical compromise would keep the trial running long enough to measure whether the improvement continues before major resources are committed.',NULL,NULL,NULL,9,'READING','PUBLISHED',NULL);
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('6a93a0e9-24b6-5f0f-a236-07192be5c545', 'MULTIPLE_CHOICE', 9, 'READING', 'Main idea and purpose', 5, NULL, NULL, 'Which statement best expresses the main idea?', '[{"label":"A","text":"A competition is cancelled without explanation."},{"label":"B","text":"The text explains how people respond to a practical problem and use evidence to guide the next step."},{"label":"C","text":"A new product is advertised to the public."},{"label":"D","text":"A character solves a problem instantly."}]'::jsonb, '{"value":"B"}'::jsonb, 'The answer summarises the central problem and response.', 'PUBLISHED', NULL, 'PREMIUM', 'EASY', 1, 'COMPREHENSION', 'Reading for meaning', NULL, '3a9e8c47-e761-5d33-b882-374177109c8d', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','6a93a0e9-24b6-5f0f-a236-07192be5c545',33,'b41074e3-8b66-56bf-bf0a-447605cfb47f','1ccf2497-632b-5f2b-bc70-e01bb9a917b1') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('9bab9be1-b408-568b-8048-b6277edda066', 'MULTIPLE_CHOICE', 9, 'READING', 'Locating information', 6, NULL, NULL, 'Which detail best supports the main idea?', '[{"label":"A","text":"The project is held outdoors."},{"label":"B","text":"The group uses a timetable."},{"label":"C","text":"The group changes its approach after comparing information with what is happening."},{"label":"D","text":"The volunteers arrive in the afternoon."}]'::jsonb, '{"value":"C"}'::jsonb, 'This detail directly describes the change that drives the text.', 'PUBLISHED', NULL, 'PREMIUM', 'MEDIUM', 1, 'COMPREHENSION', 'Reading for meaning', NULL, '3a9e8c47-e761-5d33-b882-374177109c8d', TRUE, NULL) ;
