INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('4ae18bc4-8946-5b0f-bcf0-043abc24aaa4','TEXT','B_LATE passage 2','The library repair project project at the local surf club began with a simple observation. Sienna noticed that the first plan treated several small problems as though they were the same problem. The team changed its method: they recorded each issue, tested one change at a time and compared the new result with the original notes.
