INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('576d1539-1a8c-5de2-9cb8-f46382656a35', 'MULTIPLE_CHOICE', 9, 'READING', 'Author purpose', 5, NULL, NULL, 'What is the author''s main purpose?', '[{"label":"A","text":"To explain an approach to solving a practical problem and why it is useful."},{"label":"B","text":"To provide cooking directions."},{"label":"C","text":"To tell a joke."},{"label":"D","text":"To advertise a service."}]'::jsonb, '{"value":"A"}'::jsonb, 'The text explains an approach and its implications.', 'PUBLISHED', NULL, 'PREMIUM', 'EASY', 1, 'ANALYSIS', 'Reading for meaning', NULL, '4ae18bc4-8946-5b0f-bcf0-043abc24aaa4', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','576d1539-1a8c-5de2-9cb8-f46382656a35',47,'b41074e3-8b66-56bf-bf0a-447605cfb47f','1ccf2497-632b-5f2b-bc70-e01bb9a917b1') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('968ac326-0b94-5c61-9aee-435a02a2c2e2', 'MULTIPLE_CHOICE', 9, 'READING', 'Evaluation', 6, NULL, NULL, 'Which evaluation of the author''s viewpoint is best supported?', '[{"label":"A","text":"The author rejects all trialling."},{"label":"B","text":"The author supports careful testing rather than relying on an untested first idea."},{"label":"C","text":"The author prefers decisions made without evidence."},{"label":"D","text":"The author says results never matter."}]'::jsonb, '{"value":"B"}'::jsonb, 'The text consistently values testing and evidence.', 'PUBLISHED', NULL, 'PREMIUM', 'MEDIUM', 1, 'ANALYSIS', 'Reading for meaning', NULL, '4ae18bc4-8946-5b0f-bcf0-043abc24aaa4', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','968ac326-0b94-5c61-9aee-435a02a2c2e2',48,'b41074e3-8b66-56bf-bf0a-447605cfb47f','1ccf2497-632b-5f2b-bc70-e01bb9a917b1') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('b1b22086-8c01-5d41-965b-ca095cb552c7','TEXT','C passage 1','The coastal weather station project at the local surf club began with a simple observation. Sienna noticed that the first plan treated several small problems as though they were the same problem. The team changed its method: they recorded each issue, tested one change at a time and compared the new result with the original notes.
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('e3e18c0e-1eca-59a7-8d3a-1a676282a753', 'MULTIPLE_CHOICE', 9, 'READING', 'Main idea and purpose', 5, NULL, NULL, 'Which statement best expresses the main idea?', '[{"label":"A","text":"A competition is cancelled without explanation."},{"label":"B","text":"The text explains how people respond to a practical problem and use evidence to guide the next step."},{"label":"C","text":"A new product is advertised to the public."},{"label":"D","text":"A character solves a problem instantly."}]'::jsonb, '{"value":"B"}'::jsonb, 'The answer summarises the central problem and response.', 'PUBLISHED', NULL, 'PREMIUM', 'EASY', 1, 'COMPREHENSION', 'Reading for meaning', NULL, 'b1b22086-8c01-5d41-965b-ca095cb552c7', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','e3e18c0e-1eca-59a7-8d3a-1a676282a753',49,'b41074e3-8b66-56bf-bf0a-447605cfb47f','2afde54b-7d9f-5861-ba0f-e9394b54eb37') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('254ac3d8-fd36-5806-b74d-66ca2327be8f', 'MULTIPLE_CHOICE', 9, 'READING', 'Locating information', 6, NULL, NULL, 'Which detail best supports the main idea?', '[{"label":"A","text":"The project is held outdoors."},{"label":"B","text":"The group uses a timetable."},{"label":"C","text":"The group changes its approach after comparing information with what is happening."},{"label":"D","text":"The volunteers arrive in the afternoon."}]'::jsonb, '{"value":"C"}'::jsonb, 'This detail directly describes the change that drives the text.', 'PUBLISHED', NULL, 'PREMIUM', 'MEDIUM', 1, 'COMPREHENSION', 'Reading for meaning', NULL, 'b1b22086-8c01-5d41-965b-ca095cb552c7', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','254ac3d8-fd36-5806-b74d-66ca2327be8f',50,'b41074e3-8b66-56bf-bf0a-447605cfb47f','2afde54b-7d9f-5861-ba0f-e9394b54eb37') ON CONFLICT (exam_id,question_id) DO NOTHING;
