INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('d2549a72-d6df-5741-b44e-044688e2e51e', 'MULTIPLE_CHOICE', 9, 'READING', 'Author purpose', 5, NULL, NULL, 'What is the author''s main purpose?', '[{"label":"A","text":"To explain an approach to solving a practical problem and why it is useful."},{"label":"B","text":"To provide cooking directions."},{"label":"C","text":"To tell a joke."},{"label":"D","text":"To advertise a service."}]'::jsonb, '{"value":"A"}'::jsonb, 'The text explains an approach and its implications.', 'PUBLISHED', NULL, 'PREMIUM', 'EASY', 1, 'ANALYSIS', 'Reading for meaning', NULL, 'f4ba26d7-149e-5387-aa65-bf206bad3238', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','d2549a72-d6df-5741-b44e-044688e2e51e',63,'b41074e3-8b66-56bf-bf0a-447605cfb47f','2afde54b-7d9f-5861-ba0f-e9394b54eb37') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('1a487881-b6bc-56a0-81b8-71a29d7c63f8', 'MULTIPLE_CHOICE', 9, 'READING', 'Evaluation', 6, NULL, NULL, 'Which evaluation of the author''s viewpoint is best supported?', '[{"label":"A","text":"The author rejects all trialling."},{"label":"B","text":"The author supports careful testing rather than relying on an untested first idea."},{"label":"C","text":"The author prefers decisions made without evidence."},{"label":"D","text":"The author says results never matter."}]'::jsonb, '{"value":"B"}'::jsonb, 'The text consistently values testing and evidence.', 'PUBLISHED', NULL, 'PREMIUM', 'MEDIUM', 1, 'ANALYSIS', 'Reading for meaning', NULL, 'f4ba26d7-149e-5387-aa65-bf206bad3238', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','1a487881-b6bc-56a0-81b8-71a29d7c63f8',64,'b41074e3-8b66-56bf-bf0a-447605cfb47f','2afde54b-7d9f-5861-ba0f-e9394b54eb37') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('e4db39c2-1921-55f4-8353-769223dd470a','TEXT','C_EARLY passage 1','At the river field trip, the wetland boardwalk project divided volunteers into small teams. One team wanted to begin immediately, while another argued for a short planning session. Mia listened to both sides and suggested a trial that would reveal which approach worked best. By the end of the afternoon, the group had discovered that the best solution was not the fastest idea or the most complicated one. It was the idea that made the next decision easier.',NULL,NULL,NULL,9,'READING','PUBLISHED',NULL);
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('1526d624-d05e-5128-bfdc-fdca935dfe32', 'MULTIPLE_CHOICE', 9, 'READING', 'Main idea and purpose', 6, NULL, NULL, 'Which statement best expresses the main idea?', '[{"label":"A","text":"A competition is cancelled without explanation."},{"label":"B","text":"The text explains how people respond to a practical problem and use evidence to guide the next step."},{"label":"C","text":"A new product is advertised to the public."},{"label":"D","text":"A character solves a problem instantly."}]'::jsonb, '{"value":"B"}'::jsonb, 'The answer summarises the central problem and response.', 'PUBLISHED', NULL, 'PREMIUM', 'MEDIUM', 1, 'COMPREHENSION', 'Reading for meaning', NULL, 'e4db39c2-1921-55f4-8353-769223dd470a', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','1526d624-d05e-5128-bfdc-fdca935dfe32',65,'b41074e3-8b66-56bf-bf0a-447605cfb47f','74148fa8-d00a-56be-8cfa-39b45a434679') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('d0b0225d-ba94-510b-a48c-e30595227d69', 'MULTIPLE_CHOICE', 9, 'READING', 'Locating information', 7, NULL, NULL, 'Which detail best supports the main idea?', '[{"label":"A","text":"The project is held outdoors."},{"label":"B","text":"The group uses a timetable."},{"label":"C","text":"The group changes its approach after comparing information with what is happening."},{"label":"D","text":"The volunteers arrive in the afternoon."}]'::jsonb, '{"value":"C"}'::jsonb, 'This detail directly describes the change that drives the text.', 'PUBLISHED', NULL, 'PREMIUM', 'HARD', 1, 'COMPREHENSION', 'Reading for meaning', NULL, 'e4db39c2-1921-55f4-8353-769223dd470a', TRUE, NULL) ;
