INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('615f3b27-de55-5091-82b6-4faf1e5b1ee3', 'MULTIPLE_CHOICE', 9, 'READING', 'Author purpose', 6, NULL, NULL, 'What is the author''s main purpose?', '[{"label":"A","text":"To explain an approach to solving a practical problem and why it is useful."},{"label":"B","text":"To provide cooking directions."},{"label":"C","text":"To tell a joke."},{"label":"D","text":"To advertise a service."}]'::jsonb, '{"value":"A"}'::jsonb, 'The text explains an approach and its implications.', 'PUBLISHED', NULL, 'PREMIUM', 'MEDIUM', 1, 'ANALYSIS', 'Reading for meaning', NULL, 'caf51477-e001-54e6-8fff-454e4dd4aa68', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','615f3b27-de55-5091-82b6-4faf1e5b1ee3',79,'b41074e3-8b66-56bf-bf0a-447605cfb47f','74148fa8-d00a-56be-8cfa-39b45a434679') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('fc0ed18b-3d17-536e-90e5-cff54074e189', 'MULTIPLE_CHOICE', 9, 'READING', 'Evaluation', 7, NULL, NULL, 'Which evaluation of the author''s viewpoint is best supported?', '[{"label":"A","text":"The author rejects all trialling."},{"label":"B","text":"The author supports careful testing rather than relying on an untested first idea."},{"label":"C","text":"The author prefers decisions made without evidence."},{"label":"D","text":"The author says results never matter."}]'::jsonb, '{"value":"B"}'::jsonb, 'The text consistently values testing and evidence.', 'PUBLISHED', NULL, 'PREMIUM', 'HARD', 1, 'ANALYSIS', 'Reading for meaning', NULL, 'caf51477-e001-54e6-8fff-454e4dd4aa68', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','fc0ed18b-3d17-536e-90e5-cff54074e189',80,'b41074e3-8b66-56bf-bf0a-447605cfb47f','74148fa8-d00a-56be-8cfa-39b45a434679') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('84c1e5fd-c078-5c96-abc4-7512ea494f6b','TEXT','D passage 1','Some people in the school canteen support expanding the local theatre rehearsal project, while others want to see more evidence first. Supporters point to improved participation and clearer results from the trial. Critics agree the early signs are useful but argue that a larger rollout should happen in stages. A practical compromise would keep the trial running long enough to measure whether the improvement continues before major resources are committed.',NULL,NULL,NULL,9,'READING','PUBLISHED',NULL);
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('049fda66-2bf4-521c-a289-75f1cd1817f8', 'MULTIPLE_CHOICE', 9, 'READING', 'Main idea and purpose', 6, NULL, NULL, 'Which statement best expresses the main idea?', '[{"label":"A","text":"A competition is cancelled without explanation."},{"label":"B","text":"The text explains how people respond to a practical problem and use evidence to guide the next step."},{"label":"C","text":"A new product is advertised to the public."},{"label":"D","text":"A character solves a problem instantly."}]'::jsonb, '{"value":"B"}'::jsonb, 'The answer summarises the central problem and response.', 'PUBLISHED', NULL, 'PREMIUM', 'MEDIUM', 1, 'COMPREHENSION', 'Reading for meaning', NULL, '84c1e5fd-c078-5c96-abc4-7512ea494f6b', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','049fda66-2bf4-521c-a289-75f1cd1817f8',81,'b41074e3-8b66-56bf-bf0a-447605cfb47f','5e887f54-6ed4-5285-a10a-779cd6eaa62a') ON CONFLICT (exam_id,question_id) DO NOTHING;
