INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','8faba5a2-b3b7-5f92-b7fb-b1313870afdb',82,'b41074e3-8b66-56bf-bf0a-447605cfb47f','5e887f54-6ed4-5285-a10a-779cd6eaa62a') ON CONFLICT (exam_id,question_id) DO NOTHING;
