INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('c48132af-8ade-52a9-9d67-deb94f65c0eb','TEXT','D passage 2','The solar-powered bus stop project at the regional train service began with a simple observation. Leah noticed that the first plan treated several small problems as though they were the same problem. The team changed its method: they recorded each issue, tested one change at a time and compared the new result with the original notes.
