INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('234fa734-ae27-5711-aca8-752f3d51eec1', 'MULTIPLE_CHOICE', 9, 'READING', 'Author purpose', 6, NULL, NULL, 'What is the author''s main purpose?', '[{"label":"A","text":"To explain an approach to solving a practical problem and why it is useful."},{"label":"B","text":"To provide cooking directions."},{"label":"C","text":"To tell a joke."},{"label":"D","text":"To advertise a service."}]'::jsonb, '{"value":"A"}'::jsonb, 'The text explains an approach and its implications.', 'PUBLISHED', NULL, 'PREMIUM', 'MEDIUM', 1, 'ANALYSIS', 'Reading for meaning', NULL, 'c48132af-8ade-52a9-9d67-deb94f65c0eb', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','234fa734-ae27-5711-aca8-752f3d51eec1',95,'b41074e3-8b66-56bf-bf0a-447605cfb47f','5e887f54-6ed4-5285-a10a-779cd6eaa62a') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('d4fbc8e7-9693-5d65-b2c5-582fcf041476', 'MULTIPLE_CHOICE', 9, 'READING', 'Evaluation', 7, NULL, NULL, 'Which evaluation of the author''s viewpoint is best supported?', '[{"label":"A","text":"The author rejects all trialling."},{"label":"B","text":"The author supports careful testing rather than relying on an untested first idea."},{"label":"C","text":"The author prefers decisions made without evidence."},{"label":"D","text":"The author says results never matter."}]'::jsonb, '{"value":"B"}'::jsonb, 'The text consistently values testing and evidence.', 'PUBLISHED', NULL, 'PREMIUM', 'HARD', 1, 'ANALYSIS', 'Reading for meaning', NULL, 'c48132af-8ade-52a9-9d67-deb94f65c0eb', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','d4fbc8e7-9693-5d65-b2c5-582fcf041476',96,'b41074e3-8b66-56bf-bf0a-447605cfb47f','5e887f54-6ed4-5285-a10a-779cd6eaa62a') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('ed5cb26b-b9dd-513d-8914-ab689ab0a511','TEXT','E passage 1','The mangrove restoration project at the regional train service began with a simple observation. Arun noticed that the first plan treated several small problems as though they were the same problem. The team changed its method: they recorded each issue, tested one change at a time and compared the new result with the original notes.
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('288eeb98-d19f-502b-96ce-7c624b93386b', 'MULTIPLE_CHOICE', 9, 'READING', 'Main idea and purpose', 7, NULL, NULL, 'Which statement best expresses the main idea?', '[{"label":"A","text":"A competition is cancelled without explanation."},{"label":"B","text":"The text explains how people respond to a practical problem and use evidence to guide the next step."},{"label":"C","text":"A new product is advertised to the public."},{"label":"D","text":"A character solves a problem instantly."}]'::jsonb, '{"value":"B"}'::jsonb, 'The answer summarises the central problem and response.', 'PUBLISHED', NULL, 'PREMIUM', 'HARD', 1, 'COMPREHENSION', 'Reading for meaning', NULL, 'ed5cb26b-b9dd-513d-8914-ab689ab0a511', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','288eeb98-d19f-502b-96ce-7c624b93386b',97,'b41074e3-8b66-56bf-bf0a-447605cfb47f','e3c0bf13-84a2-51f5-b0b0-5e5b68780a8b') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('6d55dbe1-557f-5c56-82d7-733db25bb182', 'MULTIPLE_CHOICE', 9, 'READING', 'Locating information', 8, NULL, NULL, 'Which detail best supports the main idea?', '[{"label":"A","text":"The project is held outdoors."},{"label":"B","text":"The group uses a timetable."},{"label":"C","text":"The group changes its approach after comparing information with what is happening."},{"label":"D","text":"The volunteers arrive in the afternoon."}]'::jsonb, '{"value":"C"}'::jsonb, 'This detail directly describes the change that drives the text.', 'PUBLISHED', NULL, 'PREMIUM', 'HARD', 1, 'COMPREHENSION', 'Reading for meaning', NULL, 'ed5cb26b-b9dd-513d-8914-ab689ab0a511', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','6d55dbe1-557f-5c56-82d7-733db25bb182',98,'b41074e3-8b66-56bf-bf0a-447605cfb47f','e3c0bf13-84a2-51f5-b0b0-5e5b68780a8b') ON CONFLICT (exam_id,question_id) DO NOTHING;
