INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('60b85527-e485-5118-bfdc-6eb87498b2a7','TEXT','E passage 2','At the wildlife rehabilitation centre, the night market volunteers project divided volunteers into small teams. One team wanted to begin immediately, while another argued for a short planning session. Tahlia listened to both sides and suggested a trial that would reveal which approach worked best. By the end of the afternoon, the group had discovered that the best solution was not the fastest idea or the most complicated one. It was the idea that made the next decision easier.',NULL,NULL,NULL,9,'READING','PUBLISHED',NULL);
