INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('bda7630f-f831-5034-86f9-a268f0a4f386', 'MULTIPLE_CHOICE', 9, 'READING', 'Author purpose', 7, NULL, NULL, 'What is the author''s main purpose?', '[{"label":"A","text":"To explain an approach to solving a practical problem and why it is useful."},{"label":"B","text":"To provide cooking directions."},{"label":"C","text":"To tell a joke."},{"label":"D","text":"To advertise a service."}]'::jsonb, '{"value":"A"}'::jsonb, 'The text explains an approach and its implications.', 'PUBLISHED', NULL, 'PREMIUM', 'HARD', 1, 'ANALYSIS', 'Reading for meaning', NULL, '60b85527-e485-5118-bfdc-6eb87498b2a7', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','bda7630f-f831-5034-86f9-a268f0a4f386',111,'b41074e3-8b66-56bf-bf0a-447605cfb47f','e3c0bf13-84a2-51f5-b0b0-5e5b68780a8b') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('83f1bd1b-6c62-5043-b9f9-096aa6a38a17', 'MULTIPLE_CHOICE', 9, 'READING', 'Evaluation', 8, NULL, NULL, 'Which evaluation of the author''s viewpoint is best supported?', '[{"label":"A","text":"The author rejects all trialling."},{"label":"B","text":"The author supports careful testing rather than relying on an untested first idea."},{"label":"C","text":"The author prefers decisions made without evidence."},{"label":"D","text":"The author says results never matter."}]'::jsonb, '{"value":"B"}'::jsonb, 'The text consistently values testing and evidence.', 'PUBLISHED', NULL, 'PREMIUM', 'HARD', 1, 'ANALYSIS', 'Reading for meaning', NULL, '60b85527-e485-5118-bfdc-6eb87498b2a7', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','83f1bd1b-6c62-5043-b9f9-096aa6a38a17',112,'b41074e3-8b66-56bf-bf0a-447605cfb47f','e3c0bf13-84a2-51f5-b0b0-5e5b68780a8b') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('b2d71bb8-889b-55e9-922d-21c9c1918b4e','TEXT','F passage 1','At the wildlife rehabilitation centre, the stormwater gardens project divided volunteers into small teams. One team wanted to begin immediately, while another argued for a short planning session. Arun listened to both sides and suggested a trial that would reveal which approach worked best. By the end of the afternoon, the group had discovered that the best solution was not the fastest idea or the most complicated one. It was the idea that made the next decision easier.',NULL,NULL,NULL,9,'READING','PUBLISHED',NULL);
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('a502a28d-d063-5cf8-a690-a143cc474321', 'MULTIPLE_CHOICE', 9, 'READING', 'Main idea and purpose', 7, NULL, NULL, 'Which statement best expresses the main idea?', '[{"label":"A","text":"A competition is cancelled without explanation."},{"label":"B","text":"The text explains how people respond to a practical problem and use evidence to guide the next step."},{"label":"C","text":"A new product is advertised to the public."},{"label":"D","text":"A character solves a problem instantly."}]'::jsonb, '{"value":"B"}'::jsonb, 'The answer summarises the central problem and response.', 'PUBLISHED', NULL, 'PREMIUM', 'HARD', 1, 'COMPREHENSION', 'Reading for meaning', NULL, 'b2d71bb8-889b-55e9-922d-21c9c1918b4e', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('ec7e8392-9a37-5865-a857-3eceb5afb84a','a502a28d-d063-5cf8-a690-a143cc474321',113,'b41074e3-8b66-56bf-bf0a-447605cfb47f','0f962f30-ece4-5728-955c-8eb08d465393') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('910a3fa9-7efb-51ff-affc-9e93137c4206', 'MULTIPLE_CHOICE', 9, 'READING', 'Locating information', 8, NULL, NULL, 'Which detail best supports the main idea?', '[{"label":"A","text":"The project is held outdoors."},{"label":"B","text":"The group uses a timetable."},{"label":"C","text":"The group changes its approach after comparing information with what is happening."},{"label":"D","text":"The volunteers arrive in the afternoon."}]'::jsonb, '{"value":"C"}'::jsonb, 'This detail directly describes the change that drives the text.', 'PUBLISHED', NULL, 'PREMIUM', 'HARD', 1, 'COMPREHENSION', 'Reading for meaning', NULL, 'b2d71bb8-889b-55e9-922d-21c9c1918b4e', TRUE, NULL) ;
